pub(super) fn epa_metric_row(
    field: &str,
    label: &str,
    pre: f64,
    post: f64,
    fmt: &str,
) -> (bool, String, String, String, String, bool) {
    let delta = post - pre;
    let higher_is_better = matches!(
        field,
        "preference" | "evaluation" | "total_loudness_sone" | "loudness_balance"
    );
    let improved = delta.abs() < 1.0e-9 || (delta > 0.0) == higher_is_better;
    (
        improved,
        label.to_string(),
        fmt_signed(pre, fmt),
        fmt_signed(post, fmt),
        if delta.abs() < 1.0e-9 {
            "=".to_string()
        } else {
            fmt_signed(delta, "{:+.3}")
        },
        improved,
    )
}

pub(super) fn fmt_signed(value: f64, fmt: &str) -> String {
    match fmt {
        "{:+.3}" => format!("{value:+.3}"),
        _ => format!("{value:+.2}"),
    }
}

